"""Verify the finite unequal-gap sieve with integers and the gap difference."""

from math import gcd

from check_unequal_predecessor import large_pairs_by_slopes


def check(pairs):
    total = 0
    possible = []
    for d, e in pairs:
        total += 1
        g = gcd(d, e)
        common = 2**g + 1
        a = (2**d + 1) // common
        b = (2**e + 1) // common
        z = 2**(d-e) - 1
        # At either modulus the cyclic subgroup generated by 2 must contain
        # z up to sign. Both order bounds are even.
        limit = 27 * 4**d
        a = gcd(a, pow(z, 2*d, a) - 1)
        if common**3 * (a*b)**2 < limit:
            continue
        b = gcd(b, pow(z, 2*e, b) - 1)
        if common**3 * (a*b)**2 >= limit:
            possible.append((d, e))
            # Scan the original period using the full quotients independently.
            def cyclic(n, t):
                modulus = (2**n+1) // common
                value = 1 + 2**t
                largest = 1
                for _ in range(2*n):
                    largest = max(largest, gcd(modulus, value-1))
                    value = (2 * value) % modulus
                return largest
            assert common**3 * (cyclic(d, e)*cyclic(e, d))**2 < limit
    return total, possible


def small():
    for g in range(1, 29):
        for h in range(3, 2000//g + 1, 2):
            for k in range(1, h, 2):
                if h < 3*k + 1 and gcd(h, k) == 1:
                    yield g*h, g*k


if __name__ == '__main__':
    print('Primitive gap enumeration', check(small()), flush=True)
    print('Slope enumeration', check(large_pairs_by_slopes()), flush=True)
